function cors(resp) {
  resp.headers.set("Access-Control-Allow-Origin", "*");
  return resp;
}

function json(data, status) {
  return cors(new Response(JSON.stringify(data), {
    status: status || 200,
    headers: { "Content-Type": "application/json" }
  }));
}

function uuid() {
  return crypto.randomUUID();
}

function b64ToUtf8(b64) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new TextDecoder("utf-8").decode(bytes);
}

function kurzDatum(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  const tag = String(d.getDate()).padStart(2, "0");
  const monat = String(d.getMonth() + 1).padStart(2, "0");
  return tag + "." + monat + ".";
}

function istRelevant(r2, q) {
  const hay = [
    (r2.brand && r2.brand.name) || "",
    (r2.product && r2.product.name) || "",
    r2.description || ""
  ].join(" ").toLowerCase();
  const woerter = q.toLowerCase().split(/\s+/).filter(Boolean);
  return woerter.every(function (w) { return hay.indexOf(w) !== -1; });
}

const MARKT_ALIASE = [
  [/rewe/i, "Rewe"],
  [/netto/i, "Netto"],
  [/aldi/i, "Aldi"],
  [/lidl/i, "Lidl"],
  [/edeka/i, "Edeka"],
  [/kaufland/i, "Kaufland"],
  [/penny/i, "Penny"],
  [/rossmann/i, "Rossmann"],
  [/thomas\s*philipps/i, "Thomas Philipps"],
  [/trinkgut/i, "Trinkgut"],
  [/getränke\s*hoffmann/i, "Getränke Hoffmann"],
  [/sonderpreis\s*baumarkt/i, "Sonderpreis Baumarkt"],
  [/\bobi\b/i, "OBI"],
  [/hornbach/i, "Hornbach"],
  [/bauhaus/i, "Bauhaus"],
  [/\bdm\b|dm-drogerie/i, "dm"],
  [/müller/i, "Müller"]
];
function kanonischerHaendler(name) {
  if (!name) return name;
  const n = name.trim();
  for (const [regex, kanon] of MARKT_ALIASE) {
    if (regex.test(n)) return kanon;
  }
  return n;
}

function findeMenge(text) {
  if (!text) return null;
  const m = text.match(/(\d+(?:[.,]\d+)?)[\s-]?(kg|g|ml|cl|l)\b/i);
  if (!m) return null;
  return m[1].replace(".", ",") + " " + m[2].toLowerCase();
}

// --- Marktguru (deckt die meisten Supermärkte/Drogerien/Baumärkte ab) ---
async function holeMarktguruAngebote(q, plz) {
  const apiUrl = MARKTGURU_URL + "?as=web&limit=48&offset=0&q=" + encodeURIComponent(q) + "&zipCode=" + encodeURIComponent(plz);
  try {
    const r = await fetch(apiUrl, { headers: MARKTGURU_HEADERS });
    if (!r.ok) return { angebote: [], warnung: "Marktguru nicht erreichbar (" + r.status + ")", debugHaendlerRoh: [], debugAnzahlRoh: 0 };
    const data = await r.json();
    const results = Array.isArray(data.results) ? data.results : [];

    // Robuste Namensermittlung: Marktguru liefert den Händlernamen meist unter
    // advertisers[0].name, manche Einträge nutzen aber abweichende Felder.
    function rohHaendlerName(r2) {
      if (r2.advertisers && r2.advertisers[0] && r2.advertisers[0].name) return r2.advertisers[0].name;
      if (r2.advertiser && r2.advertiser.name) return r2.advertiser.name;
      if (r2.retailer && r2.retailer.name) return r2.retailer.name;
      if (r2.chain && r2.chain.name) return r2.chain.name;
      if (r2.merchant && r2.merchant.name) return r2.merchant.name;
      if (typeof r2.retailerName === "string") return r2.retailerName;
      if (typeof r2.chainName === "string") return r2.chainName;
      return null;
    }

    // Debug: alle rohen Namen sammeln, die im API-Ergebnis vorkommen.
    const debugHaendlerRoh = Array.from(new Set(results.map(rohHaendlerName).map(function (n) { return n || "(kein Name gefunden)"; })));

    const angebote = results
      .filter(function (r2) { return istRelevant(r2, q); })
      .map(function (r2) {
        const haendler = kanonischerHaendler(rohHaendlerName(r2));
        const preis = typeof r2.price === "number" ? r2.price : parseFloat(r2.price);
        const alterPreis = typeof r2.oldPrice === "number" ? r2.oldPrice : null;

        const teile = [];
        if (r2.brand && r2.brand.name) teile.push(r2.brand.name);
        if (r2.product && r2.product.name && r2.product.name !== (r2.brand && r2.brand.name)) {
          teile.push(r2.product.name);
        }
        let name = teile.length ? teile.join(" ") : (r2.description || q);
        if (name.length > 60) name = name.slice(0, 57) + "…";

        const gueltig = Array.isArray(r2.validityDates) && r2.validityDates[0] ? r2.validityDates[0] : null;
        const menge = findeMenge(r2.description) || (r2.product && findeMenge(r2.product.description));

        return {
          beschreibung: name,
          haendler: haendler || "Unbekannt",
          preis: isNaN(preis) ? null : preis,
          alterPreis: alterPreis,
          menge: menge,
          imAngebot: true,
          gueltigVon: gueltig ? kurzDatum(gueltig.from) : null,
          gueltigBis: gueltig ? kurzDatum(gueltig.to) : null
        };
      })
      .filter(function (a) { return a.haendler !== "Unbekannt"; });

    return { angebote: angebote, warnung: null, debugHaendlerRoh: debugHaendlerRoh, debugAnzahlRoh: results.length };
  } catch (e) {
    return { angebote: [], warnung: "Fehler beim Abruf: " + e.message, debugHaendlerRoh: [], debugAnzahlRoh: 0 };
  }
}

// --- Aldi Nord separat, da Marktguru Aldi kaum/unzuverlässig abdeckt ---
// Nutzt die öffentliche (Search-Only) Algolia-Schnittstelle, die auch
// aldi-nord.de selbst für die eigene Produktsuche verwendet.
const ALDI_ALGOLIA_APP_ID = "R971XDJHE1";
const ALDI_ALGOLIA_API_KEY = "094afedaf99de404c0d1a62a9cf992b6";
const ALDI_ALGOLIA_URL = "https://r971xdjhe1-dsn.algolia.net/1/indexes/*/queries";
const ALDI_ALGOLIA_INDEX = "an_prd_de_de_products2";

async function holeAldiAngebote(q) {
  try {
    const authQuery = "?x-algolia-agent=" + encodeURIComponent("Fuchs-App") +
      "&x-algolia-api-key=" + ALDI_ALGOLIA_API_KEY +
      "&x-algolia-application-id=" + ALDI_ALGOLIA_APP_ID;
    const body = JSON.stringify({
      requests: [{
        indexName: ALDI_ALGOLIA_INDEX,
        params: "query=" + encodeURIComponent(q) + "&hitsPerPage=50"
      }]
    });
    const r = await fetch(ALDI_ALGOLIA_URL + authQuery, {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded" },
      body: body
    });
    if (!r.ok) return [];
    const data = await r.json();
    const hits = (data.results && data.results[0] && data.results[0].hits) || [];
    return hits
      // Nur echte aktuelle Angebote (mit Aktionspreis-Zeitraum) zählen,
      // nicht das komplette Dauersortiment.
      .filter(function (h) { return Array.isArray(h.promotionPrices) && h.promotionPrices.length > 0; })
      .map(function (h) {
        const promo = h.promotionPrices[0];
        const teile = [];
        if (h.brandName) teile.push(h.brandName);
        if (h.name && h.name !== h.brandName) teile.push(h.name);
        let name = teile.length ? teile.join(" ") : (h.shortDescription || q);
        if (name.length > 60) name = name.slice(0, 57) + "…";
        const menge = findeMenge(h.salesUnit) || findeMenge(h.shortDescription);
        // Aldi markiert Aktionsartikel mit begrenzter Stückzahl auf dem
        // Preisschild mit einem "*" – das steckt in legalInformation.
        const hatHinweis = Array.isArray(h.legalInformation) && h.legalInformation.length > 0;
        return {
          beschreibung: name,
          haendler: "Aldi",
          preis: typeof promo.priceValue === "number" ? promo.priceValue : null,
          alterPreis: (promo.strikePrice && typeof promo.strikePrice.strikePriceValue === "number") ? promo.strikePrice.strikePriceValue : null,
          menge: menge,
          imAngebot: true,
          hinweis: hatHinweis,
          hinweisText: hatHinweis ? "Aktionsartikel stehen nur in begrenzter Anzahl zur Verfügung. Sie können daher schon am Vormittag des Aktionstages kurz nach Aktionsbeginn ausverkauft sein." : null,
          gueltigVon: promo.validFromLocalDate ? kurzDatum(promo.validFromLocalDate) : null,
          gueltigBis: promo.validUntilLocalDate ? kurzDatum(promo.validUntilLocalDate) : null
        };
      });
  } catch (e) {
    return [];
  }
}

async function handleAngebote(url, env) {
  const q = url.searchParams.get("q");
  const plz = url.searchParams.get("plz") || "30966";
  if (!q) return json({ error: "q fehlt" }, 400);

  const [marktguru, aldiAngebote] = await Promise.all([
    holeMarktguruAngebote(q, plz),
    holeAldiAngebote(q)
  ]);

  const angebote = marktguru.angebote.concat(aldiAngebote);

  // Pro Händler zuerst je einen Treffer sichern, damit seltenere oder
  // spät in der API-Antwort auftauchende Händler (z.B. Sonderpreis
  // Baumarkt) nicht von vielen Treffern anderer Händler verdrängt werden.
  // WICHTIG: der Deckel greift nur bei den zusätzlichen Treffern (rest) –
  // jeder Händler mit mindestens einem Treffer bleibt garantiert erhalten,
  // auch wenn dadurch mehr als der alte Deckel von 10 herauskommt.
  const geseheneHaendler = new Set();
  const zuerst = [];
  const rest = [];
  for (const a of angebote) {
    if (!geseheneHaendler.has(a.haendler)) {
      geseheneHaendler.add(a.haendler);
      zuerst.push(a);
    } else {
      rest.push(a);
    }
  }
  const deckel = Math.max(20, zuerst.length);
  const sortiert = zuerst.concat(rest.slice(0, Math.max(0, deckel - zuerst.length)))
    .sort(function (a, b) {
      const pa = typeof a.preis === "number" ? a.preis : Infinity;
      const pb = typeof b.preis === "number" ? b.preis : Infinity;
      return pa - pb;
    });

  const debugHaendlerRoh = marktguru.debugHaendlerRoh.concat(
    ["Aldi (eigene Quelle: " + aldiAngebote.length + " Treffer)"]
  );

  return json({
    angebote: sortiert,
    warnung: marktguru.warnung,
    debugHaendlerRoh: debugHaendlerRoh,
    debugAnzahlRoh: marktguru.debugAnzahlRoh
  });
}

async function handleGetListen(url, env) {
  const gruppe = url.searchParams.get("gruppe");
  if (!gruppe) return json({ error: "gruppe fehlt" }, 400);
  let { results } = await env.DB.prepare(
    "SELECT id, name FROM listen WHERE gruppe_code = ? ORDER BY erstellt_am ASC"
  ).bind(gruppe).all();
  if (!results.length) {
    const idWoche = uuid();
    const idBaumarkt = uuid();
    const now = Date.now();
    await env.DB.prepare(
      "INSERT INTO listen (id, gruppe_code, name, erstellt_am) VALUES (?, ?, ?, ?)"
    ).bind(idWoche, gruppe, "Wocheneinkauf", new Date(now).toISOString()).run();
    await env.DB.prepare(
      "INSERT INTO listen (id, gruppe_code, name, erstellt_am) VALUES (?, ?, ?, ?)"
    ).bind(idBaumarkt, gruppe, "Baumarkt", new Date(now + 1).toISOString()).run();
    results = [{ id: idWoche, name: "Wocheneinkauf" }, { id: idBaumarkt, name: "Baumarkt" }];
  } else if (!results.some(function (l) { return l.name === "Baumarkt"; })) {
    // Bestehende Gruppen ohne Baumarkt-Liste nachträglich ergänzen
    const idBaumarkt = uuid();
    await env.DB.prepare(
      "INSERT INTO listen (id, gruppe_code, name, erstellt_am) VALUES (?, ?, ?, ?)"
    ).bind(idBaumarkt, gruppe, "Baumarkt", new Date().toISOString()).run();
    results.push({ id: idBaumarkt, name: "Baumarkt" });
  }
  return json({ listen: results });
}

async function handleAddListe(request, env) {
  const body = await request.json();
  const gruppe = body.gruppe;
  const name = (body.name || "").trim();
  if (!gruppe || !name) return json({ error: "gruppe und name erforderlich" }, 400);
  const id = uuid();
  await env.DB.prepare(
    "INSERT INTO listen (id, gruppe_code, name, erstellt_am) VALUES (?, ?, ?, ?)"
  ).bind(id, gruppe, name, new Date().toISOString()).run();
  return json({ liste: { id: id, name: name } });
}

const ERLEDIGT_AUFBEWAHRUNG_MS = 2 * 60 * 60 * 1000;

async function handleGetItems(url, env) {
  const listenId = url.searchParams.get("listen_id");
  if (!listenId) return json({ error: "listen_id fehlt" }, 400);

  // Seit mehr als 2 Stunden erledigte Artikel automatisch entfernen
  const grenze = new Date(Date.now() - ERLEDIGT_AUFBEWAHRUNG_MS).toISOString();
  await env.DB.prepare(
    "DELETE FROM items WHERE listen_id = ? AND erledigt = 1 AND erledigt_am IS NOT NULL AND erledigt_am < ?"
  ).bind(listenId, grenze).run();

  const { results } = await env.DB.prepare(
    "SELECT * FROM items WHERE listen_id = ? ORDER BY hinzugefuegt_am ASC"
  ).bind(listenId).all();
  const items = results.map(function (row) {
    return {
      id: row.id,
      name: row.name,
      erledigt: !!row.erledigt,
      erledigtAm: row.erledigt_am || null,
      anzahl: row.anzahl || 1,
      wichtig: !!row.wichtig,
      ohneAngebot: !!row.ohne_angebot,
      angebote: row.angebote_json ? JSON.parse(row.angebote_json) : []
    };
  });
  return json({ items: items });
}

async function handleAddItem(request, env) {
  const body = await request.json();
  const listenId = body.listen_id;
  const name = (body.name || "").trim();
  const ohneAngebot = !!body.ohne_angebot;
  if (!listenId || !name) return json({ error: "listen_id und name erforderlich" }, 400);
  const id = uuid();
  await env.DB.prepare(
    "INSERT INTO items (id, listen_id, liste_code, name, erledigt, hinzugefuegt_am, ohne_angebot) VALUES (?, ?, ?, ?, 0, ?, ?)"
  ).bind(id, listenId, listenId, name, new Date().toISOString(), ohneAngebot ? 1 : 0).run();
  return json({ item: { id: id, name: name, erledigt: false, erledigtAm: null, anzahl: 1, wichtig: false, ohneAngebot: ohneAngebot, angebote: [] } });
}

async function handlePatchItem(request, env, id) {
  const body = await request.json();
  if (typeof body.erledigt !== "undefined") {
    const erledigtAm = body.erledigt ? new Date().toISOString() : null;
    await env.DB.prepare("UPDATE items SET erledigt = ?, erledigt_am = ? WHERE id = ?")
      .bind(body.erledigt ? 1 : 0, erledigtAm, id).run();
  }
  if (typeof body.anzahl !== "undefined") {
    const anzahl = Math.max(1, parseInt(body.anzahl, 10) || 1);
    await env.DB.prepare("UPDATE items SET anzahl = ? WHERE id = ?").bind(anzahl, id).run();
  }
  if (typeof body.wichtig !== "undefined") {
    await env.DB.prepare("UPDATE items SET wichtig = ? WHERE id = ?").bind(body.wichtig ? 1 : 0, id).run();
  }
  if (typeof body.ohne_angebot !== "undefined") {
    await env.DB.prepare("UPDATE items SET ohne_angebot = ? WHERE id = ?").bind(body.ohne_angebot ? 1 : 0, id).run();
  }
  if (typeof body.angebote !== "undefined") {
    await env.DB.prepare("UPDATE items SET angebote_json = ?, angebote_stand = ? WHERE id = ?")
      .bind(JSON.stringify(body.angebote), new Date().toISOString(), id).run();
  }
  return json({ ok: true });
}

async function handleDeleteItem(env, id) {
  await env.DB.prepare("DELETE FROM items WHERE id = ?").bind(id).run();
  return json({ ok: true });
}

// --- Barcode-Produktsuche: OpenFoodFacts (Lebensmittel) + UPCItemDB
// (allgemeine Produkte, hilft bei Baumarkt-/Drogerie-Artikeln) ---
function embCodeAusText(embRaw) {
  if (!embRaw) return null;
  const m = embRaw.toUpperCase().match(/DE[\s-]*([A-ZÄÖÜ]{2,3})[\s-]*(\d{2,6})/);
  return m ? ("DE " + m[1] + " " + m[2] + " EG") : null;
}

// Sucht bei OpenFoodFacts nach ähnlichen Produkten (gleicher Name/Marke) und schaut,
// ob einer der anderen Einträge einen Rückverfolgbarkeits-Code hinterlegt hat – bei
// Duplikaten in der Datenbank ist die Datenqualität oft unterschiedlich gut.
async function embCodeUeberAehnlicheProdukteSuchen(name, brand) {
  const begriff = [brand, name].filter(Boolean).join(" ").trim();
  if (!begriff) return null;
  try {
    const r = await fetch(
      "https://world.openfoodfacts.org/cgi/search.pl?json=1&page_size=20&search_simple=1&action=process&search_terms=" +
      encodeURIComponent(begriff)
    );
    if (!r.ok) return null;
    const data = await r.json();
    const produkte = (data && data.products) || [];
    for (const p2 of produkte) {
      const code = embCodeAusText(p2.emb_codes || (Array.isArray(p2.emb_codes_tags) ? p2.emb_codes_tags.join(",") : ""));
      if (code) return code;
    }
  } catch (e) { /* kein Fallback gefunden */ }
  return null;
}

async function handleBarcode(url, env) {
  const code = (url.searchParams.get("code") || "").trim();
  const modus = url.searchParams.get("modus") || "";
  if (!code) return json({ error: "code fehlt" }, 400);

  // 1) OpenFoodFacts – gut für Lebensmittel
  try {
    const r = await fetch("https://world.openfoodfacts.org/api/v2/product/" + encodeURIComponent(code) + ".json");
    if (r.ok) {
      const data = await r.json();
      const p = data && data.product;
      if (p) {
        const brand = p.brands ? p.brands.split(",")[0].trim() : null;
        const name = p.product_name_de || p.product_name ||
          p.generic_name_de || p.generic_name ||
          brand;

        // Rückverfolgbarkeits-Code (EU-Identitätskennzeichen) prüfen – zeigt den
        // tatsächlichen Herstellerbetrieb, nicht nur die Handelsmarke (wichtig bei No-Name).
        let herstellerBetrieb = null;
        let embCode = embCodeAusText(p.emb_codes || (Array.isArray(p.emb_codes_tags) ? p.emb_codes_tags.join(",") : ""));

        // Nur im Hersteller-Scanner (nicht beim schnellen Hinzufügen zur Liste):
        // falls dieser Eintrag keinen Code hat, bei ähnlichen Produkten nachschauen.
        if (!embCode && modus === "hersteller") {
          embCode = await embCodeUeberAehnlicheProdukteSuchen(name, brand);
        }

        if (embCode) {
          const betrieb = await betriebNachschlagen(embCode);
          if (betrieb.gefunden) herstellerBetrieb = betrieb;
        }

        if (name || herstellerBetrieb) {
          return json({
            name: name,
            brand: brand,
            hersteller_betrieb: herstellerBetrieb,
            quelle: "OpenFoodFacts"
          });
        }
      }
    }
  } catch (e) { /* weiter zur nächsten Quelle */ }

  // 2) UPCItemDB – breiter aufgestellt, auch Nicht-Lebensmittel
  try {
    const r2 = await fetch("https://api.upcitemdb.com/prod/trial/lookup?upc=" + encodeURIComponent(code), {
      headers: { "Accept": "application/json" }
    });
    if (r2.ok) {
      const data2 = await r2.json();
      const item = data2 && Array.isArray(data2.items) && data2.items[0];
      if (item) {
        const brand = item.brand || null;
        const name = item.title || (brand ? brand + (item.description ? " " + item.description : "") : null);
        if (name) return json({ name: name, brand: brand, quelle: "UPCItemDB" });
      }
    }
  } catch (e) { /* keine weitere Quelle mehr */ }

  return json({ name: null });
}

// Sucht einen Betrieb anhand des EU-Identitätskennzeichens (z.B. "DE BY 13163 EG")
// über den öffentlichen Drittanbieter-Index identitaetskennzeichen.de,
// der auf der amtlichen BVL-Betriebsliste basiert.
async function betriebNachschlagen(raw) {
  const m = (raw || "").toUpperCase().match(/DE[\s-]*([A-ZÄÖÜ]{2,3})[\s-]*(\d{2,6})[\s-]*(EG|CE)?/);
  if (!m) {
    return { gefunden: false, grund: "format" };
  }
  const bundesland = m[1].toLowerCase();
  const nummer = m[2].toLowerCase();
  const slug = "de-" + bundesland + "-" + nummer + "-eg";
  const quelleUrl = "https://identitaetskennzeichen.de/" + slug + "/";

  try {
    const r = await fetch(quelleUrl, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; FuchsApp/1.0)" }
    });
    if (!r.ok) {
      return { gefunden: false, grund: "abruf_fehlgeschlagen", quelle_url: quelleUrl };
    }
    const html = await r.text();

    if (/kein treffer/i.test(html)) {
      return { gefunden: false, grund: "kein_treffer", quelle_url: quelleUrl };
    }

    let beschreibung = null;
    let mDesc = html.match(/<meta\s+(?:property|name)=["']og:description["']\s+content=["']([^"']+)["']/i)
      || html.match(/<meta\s+name=["']description["']\s+content=["']([^"']+)["']/i);
    if (mDesc) beschreibung = decodeHtmlEntities(mDesc[1]);

    let titel = null;
    let mTitle = html.match(/<h1[^>]*>([^<]+)<\/h1>/i) || html.match(/<title>([^<]+)<\/title>/i);
    if (mTitle) titel = decodeHtmlEntities(mTitle[1]).replace(/\s*[|–-]\s*Identitätskennzeichen.*$/i, "").trim();

    if (!beschreibung && !titel) {
      return { gefunden: false, grund: "keine_daten", quelle_url: quelleUrl };
    }

    return {
      gefunden: true,
      firma: titel,
      beschreibung: beschreibung,
      kennzeichen: "DE " + m[1].toUpperCase() + " " + m[2] + " EG",
      quelle_url: quelleUrl
    };
  } catch (e) {
    return { gefunden: false, grund: "fehler", quelle_url: quelleUrl };
  }
}

async function handleBetrieb(url, env) {
  const raw = (url.searchParams.get("code") || "").trim();
  if (!raw) return json({ error: "code fehlt" }, 400);
  const ergebnis = await betriebNachschlagen(raw);
  return json(ergebnis);
}

function decodeHtmlEntities(s) {
  return s
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS") {
      return cors(new Response(null, { status: 204 }));
    }

    if (url.pathname === "/") {
      const html = b64ToUtf8(HTML_B64);
      return new Response(html, {
        headers: { "Content-Type": "text/html; charset=UTF-8", "Cache-Control": "no-cache" }
      });
    }

    if (url.pathname === "/manifest.json") {
      return new Response(MANIFEST_JSON, {
        headers: { "Content-Type": "application/json", "Cache-Control": "no-cache" }
      });
    }

    if (url.pathname === "/sw.js") {
      return new Response(SW_JS, {
        headers: { "Content-Type": "application/javascript; charset=UTF-8", "Cache-Control": "no-cache" }
      });
    }

    if (url.pathname === "/icon-192.png") {
      const bytes = Uint8Array.from(atob(ICON_192_B64), c => c.charCodeAt(0));
      return new Response(bytes, {
        headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" }
      });
    }

    if (url.pathname === "/icon-512.png") {
      const bytes = Uint8Array.from(atob(ICON_512_B64), c => c.charCodeAt(0));
      return new Response(bytes, {
        headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" }
      });
    }

    if (url.pathname === "/api/angebote" && request.method === "GET") {
      return handleAngebote(url, env);
    }

    if (url.pathname === "/api/barcode" && request.method === "GET") {
      return handleBarcode(url, env);
    }

    if (url.pathname === "/api/betrieb" && request.method === "GET") {
      return handleBetrieb(url, env);
    }

    if (url.pathname === "/api/listen" && request.method === "GET") {
      return handleGetListen(url, env);
    }

    if (url.pathname === "/api/listen" && request.method === "POST") {
      return handleAddListe(request, env);
    }

    if (url.pathname === "/api/items" && request.method === "GET") {
      return handleGetItems(url, env);
    }

    if (url.pathname === "/api/items" && request.method === "POST") {
      return handleAddItem(request, env);
    }

    const itemMatch = url.pathname.match(/^\/api\/items\/([^/]+)$/);
    if (itemMatch && request.method === "PATCH") {
      return handlePatchItem(request, env, itemMatch[1]);
    }
    if (itemMatch && request.method === "DELETE") {
      return handleDeleteItem(env, itemMatch[1]);
    }

    return new Response("Not found", { status: 404 });
  }
};
